-- Keep the former preview listings in the protected admin catalogue, but do
-- not expose them to customers until the client reviews and publishes them.
UPDATE "catalog_listings"
SET "isPublished" = FALSE,
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" IN (
  -- Names generated by seed-starter-catalog.cjs. Unpublish by stable slug so
  -- edits made to a draft cannot accidentally make starter data public.
  'asian-paints-royale-play',
  'asian-paints-royale-glitz',
  'asian-paints-royale',
  'asian-paints-ace-exterior-emulsion',
