OR (
  "description" = 'Ask the team to confirm the exact variant, pack size, colour or grade, price and current availability for your requirement.'
  AND "price" IS NULL
  AND "image" IS NULL
  AND "priceNote" IS NULL
  AND "offerLabel" IS NULL
  AND "minOrderQty" IS NULL
  AND "isInStock" = FALSE
  AND "features" = '{}'::text[]
  AND "applications" = '{}'::text[]
  AND "specifications" = '{}'::jsonb
  AND "galleryImages" = '{}'::text[]
  AND NOT EXISTS (
    SELECT 1 FROM "catalog_listing_variants" v
    WHERE v."listingId" = "catalog_listings"."id"
  )
);
